def display_data_origin_label(origin: str | None) -> str:
    raw = str(origin or REAL_DATA_ORIGIN).strip().lower()
    try:
        value = normalize_data_origin(raw)
    except Exception:
        value = raw or REAL_DATA_ORIGIN
    if value == "real":
        return "real study data"
    if value == "dummy":
        return "synthetic validation data"
    if value == "mixed_source":
        return "combined results bundle"
    return value.replace("_", " ")


def dataset_pipeline_support_summary(dataset_id: str) -> dict[str, str | bool]:
    ds = str(dataset_id or "").strip()
    if ds in PIPELINE_ENABLED_DATASET_IDS:
        return {
            "level": "full",
            "label": "Full pipeline support",
            "detail": (
                f"{ds} supports the full end-to-end workflow in this dashboard, including "
                "dataset-specific preprocessing/session defaults."
            ),
            "full_pipeline_supported": True,
        }
    return {
        "level": "limited",
        "label": "Review-only by default",
        "detail": (
            f"{ds} can be registered, inspected, and checked here, but full preprocessing-driven runs "
            "are mapped for ds003171 and ds005620."
        ),
        "full_pipeline_supported": False,
    }


def json_ready(value: Any) -> Any:
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, dict):
        return {str(k): json_ready(v) for k, v in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [json_ready(v) for v in value]
    if isinstance(value, np.generic):
        return json_ready(value.item())
    if isinstance(value, float):
        return value if math.isfinite(value) else None
    return value


