        self._managed_exit_code: int | None = None
        self._managed_log_file: str | None = None
        self._managed_last_spec: dict[str, Any] | None = None
        self._managed_queue: list[dict[str, Any]] = []
        self._managed_plan: list[dict[str, Any]] = []
        self._managed_restart_payload: dict[str, Any] | None = None
        self._managed_mixed_source_context: dict[str, Any] | None = None
        self._last_mixed_source_result: dict[str, Any] | None = None
