        self._last_import_message: str = "Dataset import profile has not been analyzed yet."
        self._last_eval_summary: dict[str, Any] | None = None
        self._last_readiness_summary: dict[str, Any] | None = None
        self._last_readiness_preview: list[dict[str, Any]] = []
        self._last_setup_report: dict[str, Any] | None = None
        self._last_dataset_profile: dict[str, Any] | None = None
        self._last_error: dict[str, Any] | None = None
        self._dataset_readiness_cache: dict[str, dict[str, Any]] = {}
        self._dataset_profile_cache: dict[str, dict[str, Any]] = {}
        self._active_selection: dict[str, Any] = {
            "dataset_id": str(cfg.dataset_id),
            "out_dir": str(cfg.out_dir),
            "data_origin": str(cfg.data_origin),
            "bids_root": None,
            "modality_profile": "auto",
            "subjects": [],
        }
        self._dataset_registry: dict[str, dict[str, Any]] = {}
        self._control_cache_dir = self._repo_root / "outputs" / "dashboard_control"
        self._control_cache_dir.mkdir(parents=True, exist_ok=True)
        self._registry_file = self._control_cache_dir / "dataset_registry.json"
        self._readiness_summary_file = self._control_cache_dir / "last_mpc_readiness_summary.json"
        self._readiness_preview_file = self._control_cache_dir / "last_mpc_readiness_preview.json"
        self._readiness_cache_file = self._control_cache_dir / "dataset_mpc_readiness_cache.json"
        self._setup_report_file = self._control_cache_dir / "last_setup_report.json"
        self._dataset_profile_file = self._control_cache_dir / "dataset_profile_cache.json"
        self._last_error_file = self._control_cache_dir / "last_error.json"
        self._last_mixed_source_file = self._control_cache_dir / "last_mixed_source_result.json"
        self._load_control_cache()

        # Keep the full timeline for the active run.
        self.history: list[dict[str, Any]] = []
        self._history_run_pid: int | None = None
        self._history_run_start_unix: float | None = None
        self._self_proc = psutil.Process(os.getpid())
        self._logical_cpus = int(psutil.cpu_count(logical=True) or 1)
        self._proc_cpu_last: dict[int, tuple[float, float]] = {}
        self._vm_prev: dict[str, Any] | None = None
        self._vm_stat_cache: dict[str, Any] = {"t": 0.0, "data": None}
        self._memory_pressure_cache: dict[str, Any] = {"t": 0.0, "data": None}
        self._pmset_cache: dict[str, Any] = {"t": 0.0, "text": "", "cpu_speed_limit_pct": None}
        self._battery_temp_cache: dict[str, Any] = {"t": 0.0, "battery_temp_c": None, "note": "n/a"}
        self._powermetrics_cache: dict[str, Any] = {"t": 0.0, "available": False, "fresh": False}
